private bool DeleteData()
{
    DataRow[] rowsSelected = dtbData.Select("IsSelected=1");
    if (rowsSelected.Length == 0)
    {
        int[] arrRowIndex = gvData.GetSelectedRows();
        if (arrRowIndex.Length == 0)
        {
            MessageManager.Warning("Bạn phải chọn ít nhất một sinh viên!");
            return false;
        }

        rowsSelected = new DataRow[arrRowIndex.Length];
        for (int i = 0; i < arrRowIndex.Length; i++)
            rowsSelected[i] = gvData.GetDataRow(arrRowIndex[i]);
    }

    SIM_SummaryEthicMark obj = new SIM_SummaryEthicMark();
    obj.BeginTransaction();
    foreach (DataRow drw in rowsSelected)
    {
        if (drw["YearID"] == DBNull.Value || drw["YearID"].ToString() == "")
        {
            MessageManager.Warning(String.Format("Sinh viên {0} chưa có điểm rèn luyện để xóa!", drw["StudentCode"]));
            obj.RollBackTransaction();
            return false;
        }

        SIM_SummaryEthicMark item = new SIM_SummaryEthicMark();
        item.IDB = obj.IDB;
        if (!item.Delete(Convert.ToInt64(drw["StudentID"]), Convert.ToInt32(drw["YearID"])))
        {
            ErrorManager.Error("Xóa điểm rèn luyện bị lỗi!");
            obj.RollBackTransaction();
            return false;
        }
    }
    obj.CommitTransaction();
    return true;
}

